#pragma comment(linker, "/STACK:100000000000")
typedef long long ll;
typedef unsigned long long ull;
typedef long double lld;
typedef pair<int, int> PII;
typedef pair<ll, ll> PLL;
typedef vector<int> VI;
typedef vector<string> VS;
typedef vector<double> VD;

string imposible = "IMPOSSIBLE";

string f2(string s, int N, int R, int B, int Y) {
  char Front = 'A';
  char Back = 'A';
  if (!s.empty()) {
    Front = s[0];
    Back = s.back();
  }
  for (int(i) = 0; (i) < (N); (i)++) {
    if (Back == 'R') {
      if (B > Y) {
        s += "B";
        B--;
      } else if (Y > B) {
        s += "Y";
        Y--;
      } else {
        if (B == 0 && Y == 0)
          return imposible;
        if (Front == 'B') {
          s += 'B';
          B--;
        } else {
          s += 'Y';
          Y--;
        }
      }
    } else if (Back == 'B') {
      if (R > Y) {
        s += "R";
        R--;
      } else if (Y > R) {
        s += "Y";
        Y--;
      } else {
        if (R == 0 && Y == 0)
          return imposible;
        if (Front == 'R') {
          s += 'R';
          R--;
        } else {
          s += 'Y';
          Y--;
        }
      }
    } else if (Back == 'Y') {
      if (R > B) {
        s += "R";
        R--;
      } else if (B > R) {
        s += "B";
        B--;
      } else {
        if (R == 0 && B == 0)
          return imposible;
        if (Front == 'R') {
          s += "R";
          R--;
        } else {
          s += "B";
          B--;
        }
      }
    } else {
      if (R != 0) {
        s += "R";
        R--;
      } else if (B != 0) {
        s += "B";
        B--;
      } else if (Y != 0) {
        s += "Y";
        Y--;
      } else
        return imposible;
    }
    Back = s.back();
    Front = s.front();
  }
  if (s.size() > 1 && s.back() == s.front())
    return imposible;
  return s;
}

string f(int N, int R, int O, int Y, int G, int B, int V) {
  if (G > R)
    return imposible;
  if (O > B)
    return imposible;
  if (V > Y)
    return imposible;

  if (G == R && G != 0) {
    if (O == 0 && B == 0 && V == 0 && Y == 0) {
      string res;
      for (int(i) = 0; (i) < (N / 2); (i)++)
        res += "GR";
      return res;
    } else
      return imposible;
  }
  if (O == B && O != 0) {
    if (R == 0 && G == 0 && V == 0 && Y == 0) {
      string res;
      for (int(i) = 0; (i) < (N / 2); (i)++)
        res += "OB";
      return res;
    } else
      return imposible;
  }
  if (V == Y && V != 0) {
    if (O == 0 && B == 0 && G == 0 && R == 0) {
      string res;
      for (int(i) = 0; (i) < (N / 2); (i)++)
        res += "VY";
      return res;
    } else
      return imposible;
  }
  string res[3];

  string RG;
  for (int(i) = 0; (i) < (G); (i)++)
    RG += "RG";
  if (!RG.empty())
    RG += "R";
  string BO;
  for (int(i) = 0; (i) < (O); (i)++)
    BO += "BO";
  if (!BO.empty())
    BO += "B";
  string YV;
  for (int(i) = 0; (i) < (V); (i)++)
    YV += "YV";
  if (!YV.empty())
    YV += "Y";
  if (G != 0)
    R -= (G + 1);
  if (O != 0)
    B -= (O + 1);
  if (V != 0)
    Y -= (V + 1);
  res[0] = f2(RG + BO + YV, R + B + Y, R, B, Y);
  res[1] = f2(RG + YV + BO, R + B + Y, R, B, Y);
  res[2] = f2(YV + RG + BO, R + B + Y, R, B, Y);

  for (int(i) = 0; (i) < (3); (i)++)
    if (res[i] != imposible)
      return res[i];
  return imposible;
}
