using LL = long long;

int T, cas;

string convert(string s) {
  int p, i;
  for (p = 0, i = 0; s[i]; i++) {
    if (s[i] != '?')
      while (p <= i)
        s[p++] = s[i];
  }
  if (!p)
    return s;
  while (s[--i] == '?')
    s[i] = s[p - 1];
  return s;
}

