    for (i = 0; i < n; i++) {
      string s;
      cin >> s;
      s = convert(s);
      a.push_back(s);
      if (s[0] != '?')
        while (p <= i)
          a[p++] = a[i];
    }
    while (a[--i][0] == '?')
      a[i] = a[p - 1];
    printf("Case #%d:\n", ++cas);
    for (auto s : a)
      printf("%s\n", s.c_str());
  }
  return 0;
}
